import { useState } from "react"
import { Badge, DataTable } from "@nifrajs/ui"

type Run = {
  id: string
  name: string
  owner: string
  status: "Ready" | "Review"
}

const runs: Run[] = [
  { id: "run-042", name: "Route audit", owner: "Maya Chen", status: "Ready" },
  { id: "run-041", name: "Schema check", owner: "Sam Lee", status: "Review" },
]

export function RunTable() {
  const [selectedKeys, setSelectedKeys] = useState<string[]>([])
  const [sortDirection, setSortDirection] = useState<"asc" | "desc">("asc")
  const orderedRuns = [...runs].sort((a, b) =>
    sortDirection === "asc" ? a.name.localeCompare(b.name) : b.name.localeCompare(a.name),
  )

  return (
    <DataTable
      caption="Recent runs"
      data={orderedRuns}
      rowKey="id"
      minWidth="560px"
      striped
      selection={{
        selectedKeys,
        onSelectedKeysChange: (keys) => setSelectedKeys(keys.map(String)),
        getRowLabel: (row) => String(row.name),
      }}
      sort={{
        key: "name",
        direction: sortDirection,
        onChange: (_key, direction) => setSortDirection(direction),
      }}
      emptyState="No runs have been recorded."
      columns={[
        { key: "name", header: "Run", width: "44%", sortable: true },
        { key: "owner", header: "Owner", width: "24%" },
        {
          key: "status",
          header: "Status",
          width: "32%",
          render: (value) => (
            <Badge size="sm" tone={value === "Ready" ? "accent" : "neutral"}>
              {String(value)}
            </Badge>
          ),
        },
      ]}
    />
  )
}

